<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"15px","lineHeight":"1.8"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:15px;line-height:1.8;margin-top:0px;margin-bottom:0px">運転免許証・マイナンバーカードなど、住所と顔写真が確認できるもの。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#6e5312"},"typography":{"fontSize":"16px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"8px"}}}} -->
<h3 class="has-text-color" style="color:#6e5312;font-size:16px;line-height:1.5;margin-top:0px;margin-bottom:8px">引き落とし口座の通帳かキャッシュカード</h3>
