<!-- wp:wdl/lw-qa-1 {"mainColor":"#14264a"} -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">審査に落ちました</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">理由は公表されません。他社での延滞歴や、短期間の複数申し込みが影響していることがあります。半年ほど間を空けてから、別のカードに申し込むほうが通りやすくなります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">在籍確認の電話が心配です</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">カード会社の担当者名は名乗らず、個人名で会社にかけてくることが多いです。本人が出られなくても、在籍が確認できれば通ることがあります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">結果の連絡が来ません</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">通常は1週間以内に届きます。迷惑メールフォルダに入っていないか確認し、それでも無ければ公式サイトの問い合わせ窓口から状況を聞いてください。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">カードが届きません</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">本人限定受取郵便は不在だと持ち帰られます。不在票の番号から再配達を依頼するか、郵便局の窓口で本人確認のうえ受け取れます。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">暗証番号を忘れました</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">マイページか電話窓口から再設定できます。カード裏面のサポート番号にかければ案内があります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto">Q<div style="background:#14264a"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="">解約するとどうなりますか</p></div><div class="open_icon" style="background:#14264a"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="color:#14264a">A<div style="background:#14264a"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="">信用情報に「解約」の記録は残りますが、それ自体が不利になることは基本的にありません。年会費が発生したあとの解約は、その年の年会費は戻らないことが多いです。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
